/* test_primal.c - reliability test suite for primal
 *
 * Every optimization test is checked THREE ways:
 *  1. primal solution vs hand-verified expected values
 *  2. full KKT / duality check using ONLY the public getters
 *  3. cross-validation LP: simplex (BAS) vs interior point (ITR)
 *
 * KKT convention (min-normalized): with s=+1 for min, s=-1 for max,
 *   c + Qx + A'y + z = 0,  z = slx + sux
 *   Y_i = s*y_i:  Y>0 <=> row i at its UPPER bound, Y<0 <=> LOWER bound
 *   Z_j = s*z_j:  Z>0 <=> var j at its UPPER bound, Z<0 <=> LOWER bound
 *   duality: dobj_min = -(sum Y_i b_i^act + sum Z_j xb_j^act) - 1/2 x'Qx
 *   strong duality: |pobj_min - dobj_min| small.
 */
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <float.h>
#include <string.h>
#include "primal.h"
#include "simplex.h"
#include "mpsio.h"
#include "linalg.h"
#include "ipm.h"
#include "presolve.h"
#include "scaling.h"
#include "socp.h"
#include "sdp.h"
#include "expcone.h"

static int n_pass = 0, n_fail = 0;
static const char *cur_name = "";

static void check(int cond, const char *what) {
    if (cond) { n_pass++; }
    else {
        n_fail++;
        printf("  FAIL [%s] %s\n", cur_name, what);
    }
}

static void check_rc(PRIMALrescodee rc, PRIMALrescodee want, const char *what) {
    if (rc == want) n_pass++;
    else {
        n_fail++;
        printf("  FAIL [%s] %s (rc=%d want %d)\n", cur_name, what, rc, want);
    }
}

static void close_enough_tol(double a, double b, double ftol, const char *what) {
    double tol = ftol * (1.0 + fabs(a) + fabs(b));
    check(fabs(a - b) <= tol, what);
    if (fabs(a - b) > tol)
        printf("       %.10g vs %.10g (diff %.3g)\n", a, b, a - b);
}

static void close_enough(double a, double b, const char *what) {
    double tol = 1e-6 * (1.0 + fabs(a) + fabs(b));
    check(fabs(a - b) <= tol, what);
    if (fabs(a - b) > tol)
        printf("       %.10g vs %.10g (diff %.3g)\n", a, b, a - b);
}

/* ---------------- KKT checker (public API only) ---------------- */

typedef struct {
    int    ok;
    double feas_p, feas_d, comp, gap;   /* violation measures */
} KKT;

static void act_bound(PRIMALboundkeye bk, double bl, double bu, double *lo, double *up) {
    switch (bk) {
        case PRIMAL_BK_LO: *lo = bl; *up = INFINITY; break;
        case PRIMAL_BK_UP: *lo = -INFINITY; *up = bu; break;
        case PRIMAL_BK_FR: *lo = -INFINITY; *up = INFINITY; break;
        case PRIMAL_BK_RA: *lo = bl; *up = bu; break;
        case PRIMAL_BK_FX: *lo = bl; *up = bl; break;
        default: *lo = -INFINITY; *up = INFINITY;
    }
}

/* verify KKT for the min-normalized problem; s = +1 min / -1 max */
static KKT kkt_check(PRIMALtask_t t, double s) {
    KKT k; k.ok = 1; k.feas_p = k.feas_d = k.comp = k.gap = 0.0;
    int nv, nc;
    PRIMAL_getnumvar(t, &nv);
    PRIMAL_getnumcon(t, &nc);

    double *x  = calloc(nv ? nv : 1, sizeof(double));
    double *y  = calloc(nc ? nc : 1, sizeof(double));
    double *slc= calloc(nc ? nc : 1, sizeof(double));
    double *suc= calloc(nc ? nc : 1, sizeof(double));
    double *slx= calloc(nv ? nv : 1, sizeof(double));
    double *sux= calloc(nv ? nv : 1, sizeof(double));
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x);
    PRIMAL_gety(t, PRIMAL_SOL_ITR, y);
    PRIMAL_getslc(t, PRIMAL_SOL_ITR, slc);
    PRIMAL_getsuc(t, PRIMAL_SOL_ITR, suc);
    PRIMAL_getslx(t, PRIMAL_SOL_ITR, slx);
    PRIMAL_getsux(t, PRIMAL_SOL_ITR, sux);

    /* primal feasibility + dual obj terms */
    double dobj_min = 0.0;
    for (int i = 0; i < nc; i++) {
        PRIMALboundkeye bk; double bl, bu, lo, up;
        PRIMAL_getconbound(t, i, &bk, &bl, &bu);
        act_bound(bk, bl, bu, &lo, &up);
        double ax = 0.0;
        for (int j = 0; j < nv; j++) {
            double aij; PRIMAL_getaij(t, i, j, &aij);
            ax += aij * x[j];
        }
        double viol = 0.0;
        if (ax < lo) viol = lo - ax;
        if (ax > up) viol = ax - up;
        if (viol > k.feas_p) k.feas_p = viol;
        /* dual objective: Y_i * b_i^act (min-normalized y) */
        double Y = s * y[i];
        if (Y > 1e-9)       dobj_min -= Y * up;
        else if (Y < -1e-9) dobj_min -= Y * lo;
        /* complementarity: |Y_i| * distance to the OTHER bound ~ irrelevant;
         * check Y is zero when row strictly inside */
        if (Y > 1e-9 && ax < up - 1e-6) {
            double c2 = Y * (up - ax);
            if (c2 > k.comp) k.comp = c2;
        }
        if (Y < -1e-9 && ax > lo + 1e-9) {
            double c2 = -Y * (ax - lo);
            if (c2 > k.comp) k.comp = c2;
        }
        /* slc/suc consistency */
        if (fabs(slc[i] - (y[i] < 0 ? y[i] : 0)) > 1e-9 ||
            fabs(suc[i] - (y[i] > 0 ? y[i] : 0)) > 1e-9) {
            if (1.0 > k.comp) k.comp = 1.0;
        }
    }
    for (int j = 0; j < nv; j++) {
        PRIMALboundkeye bk; double bl, bu, lo, up;
        PRIMAL_getvarbound(t, j, &bk, &bl, &bu);
        act_bound(bk, bl, bu, &lo, &up);
        double viol = 0.0;
        if (x[j] < lo) viol = lo - x[j];
        if (x[j] > up) viol = x[j] - up;
        if (viol > k.feas_p) k.feas_p = viol;
        double Z = s * (slx[j] + sux[j]);
        if (Z > 1e-9)       dobj_min -= Z * up;
        else if (Z < -1e-9) dobj_min -= Z * lo;
        if (Z > 1e-9 && x[j] < up - 1e-6) {
            double c2 = Z * (up - x[j]);
            if (c2 > k.comp) k.comp = c2;
        }
        if (Z < -1e-9 && x[j] > lo + 1e-6) {
            double c2 = -Z * (x[j] - lo);
            if (c2 > k.comp) k.comp = c2;
        }
    }

    /* stationarity: r = c + Qx + A'y + z (as written, min-normalized? no:
     * for max problems c is the max objective; stationarity uses the
     * original data and reported duals — identity holds per convention) */
    double cnorm = 1.0, pobj;
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &pobj);
    for (int j = 0; j < nv; j++) {
        double cj; PRIMAL_getcj(t, j, &cj);
        double r = cj;
        double qij;
        for (int k = 0; k < nv; k++) {
            PRIMAL_getqobjij(t, j, k, &qij);
            r += qij * x[k];
        }
        for (int i = 0; i < nc; i++) {
            double aij; PRIMAL_getaij(t, i, j, &aij);
            r += aij * y[i];
        }
        r += slx[j] + sux[j];
        double ar = fabs(r);
        if (ar > k.feas_d) k.feas_d = ar;
        if (fabs(cj) > cnorm) cnorm = fabs(cj);
    }

    /* duality gap (min-normalized) */
    double pobj_min = 0.0, xq = 0.0, qij;
    for (int j = 0; j < nv; j++) {
        double cj; PRIMAL_getcj(t, j, &cj);
        pobj_min += s * cj * x[j];
        for (int k = 0; k < nv; k++) {
            PRIMAL_getqobjij(t, j, k, &qij);
            xq += x[j] * s * qij * x[k];
        }
    }
    pobj_min += s * 0.0; /* cfix */
    double cfix; PRIMAL_getcfix(t, &cfix);
    pobj_min += s * cfix;
    pobj_min += 0.5 * xq;
    dobj_min -= 0.5 * xq;   /* QP dual objective includes -1/2 x'Qx */
    k.gap = fabs(pobj_min - dobj_min) / (1.0 + fabs(pobj_min));

    double scale_d = 1.0 + cnorm;
    if (k.feas_p > 1e-6) k.ok = 0;
    if (k.feas_d > 1e-6 * scale_d) k.ok = 0;
    if (k.comp   > 1e-6) k.ok = 0;
    if (k.gap    > 1e-6) k.ok = 0;

    free(x); free(y); free(slc); free(suc); free(slx); free(sux);
    return k;
}


static void expect_kkt(PRIMALtask_t t, double s) {
    KKT k = kkt_check(t, s);
    if (k.ok) { n_pass++; return; }
    n_fail++;
    printf("  FAIL [%s] KKT: fp=%g fd=%g comp=%g gap=%g\n",
           cur_name, k.feas_p, k.feas_d, k.comp, k.gap);
}

/* ---------------- problem builders ---------------- */

typedef struct {
    PRIMALenv_t env;
    PRIMALtask_t task;
} P;

static void pbegin(P *p) {
    PRIMAL_makeenv(&p->env, NULL);
    PRIMAL_maketask(p->env, 0, 0, &p->task);
}
static void pend(P *p) {
    PRIMAL_deletetask(&p->task);
    PRIMAL_deleteenv(&p->env);
}

/* T1: the example LP */
static void test_t1(void) {
    cur_name = "T1 example LP (max, EQ+LO+UP rows, RA var)";
    P p; pbegin(&p);
    PRIMALtask_t t = p.task;
    PRIMAL_appendvars(t, 4); PRIMAL_appendcons(t, 3);
    PRIMAL_putobjsense(t, PRIMAL_OBJECTIVE_SENSE_MAXIMIZE);
    double c[] = {3,1,5,1};
    for (int j = 0; j < 4; j++) PRIMAL_putcj(t, j, c[j]);
    PRIMAL_putconbound(t, 0, PRIMAL_BK_FX, 30, 30);
    PRIMAL_putconbound(t, 1, PRIMAL_BK_LO, 15, 0);
    PRIMAL_putconbound(t, 2, PRIMAL_BK_UP, 0, 25);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_LO, 0, 0);
    PRIMAL_putvarbound(t, 1, PRIMAL_BK_RA, 0, 10);
    PRIMAL_putvarbound(t, 2, PRIMAL_BK_LO, 0, 0);
    PRIMAL_putvarbound(t, 3, PRIMAL_BK_LO, 0, 0);
    int s0[] = {0,1};    double v0[] = {3,2};
    int s1[] = {0,1,2};  double v1[] = {1,1,2};
    int s2[] = {0,1};    double v2[] = {2,3};
    int s3[] = {1,2};    double v3[] = {1,3};
    PRIMAL_putacol(t, 0, 2, s0, v0);
    PRIMAL_putacol(t, 1, 3, s1, v1);
    PRIMAL_putacol(t, 2, 2, s2, v2);
    PRIMAL_putacol(t, 3, 2, s3, v3);

    PRIMALrescodee rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_OK, "optimize ok");
    PRIMALsolstae sta; PRIMAL_getsolsta(t, PRIMAL_SOL_ITR, &sta);
    check(sta == PRIMAL_SOL_STA_OPTIMAL, "solsta optimal");
    double x[4], po, yo[3];
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x);
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &po);
    close_enough(po, 250.0/3.0, "pobj=250/3");
    close_enough(x[0], 0, "x1=0");
    close_enough(x[1], 0, "x2=0");
    close_enough(x[2], 15, "x3=15");
    close_enough(x[3], 25.0/3.0, "x4=25/3");
    PRIMAL_gety(t, PRIMAL_SOL_ITR, yo);
    close_enough(yo[0], -2.5, "y1=-2.5");
    close_enough(yo[1], 0.0, "y2=0");
    close_enough(yo[2], -1.0/3.0, "y3=-1/3");
    expect_kkt(t, -1.0);
    /* cross-check with interior point */
    PRIMAL_putintparam(t, PRIMAL_IPAR_OPTIMIZER, PRIMAL_OPTIMIZER_INTPNT);
    PRIMAL_optimize(t);
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x);
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &po);
    close_enough(po, 250.0/3.0, "IPM pobj=250/3");
    expect_kkt(t, -1.0);
    pend(&p);
}

/* T2: min 2x1+3x2, x1+x2=4, x in [0,10] */
static void test_t2(void) {
    cur_name = "T2 min 2x+3y s.t. x+y=4, x,y in [0,10]";
    P p; pbegin(&p);
    PRIMALtask_t t = p.task;
    PRIMAL_appendvars(t, 2); PRIMAL_appendcons(t, 1);
    double c[] = {2,3};
    for (int j = 0; j < 2; j++) PRIMAL_putcj(t, j, c[j]);
    PRIMAL_putconbound(t, 0, PRIMAL_BK_FX, 4, 4);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_RA, 0, 10);
    PRIMAL_putvarbound(t, 1, PRIMAL_BK_RA, 0, 10);
    int s0[] = {0};    double v0[] = {1};
    int s1[] = {0};    double v1[] = {1};
    PRIMAL_putacol(t, 0, 1, s0, v0);
    PRIMAL_putacol(t, 1, 1, s1, v1);
    PRIMALrescodee rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_OK, "optimize ok");
    double x[2], po, y[1], slx[2];
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x);
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &po);
    close_enough(po, 8, "pobj=8");
    close_enough(x[0], 4, "x1=4");
    close_enough(x[1], 0, "x2=0");
    PRIMAL_gety(t, PRIMAL_SOL_ITR, y);
    close_enough(y[0], -2, "y=-2");
    PRIMAL_getslx(t, PRIMAL_SOL_ITR, slx);
    close_enough(slx[0], 0, "slx1=0");
    close_enough(slx[1], -1, "slx2=-1");
    expect_kkt(t, 1.0);
    pend(&p);
}

/* T3: min x1, x1+x2=5, x1-x2=1, vars FR */
static void test_t3(void) {
    cur_name = "T3 min x1, two EQ rows, FR vars";
    P p; pbegin(&p);
    PRIMALtask_t t = p.task;
    PRIMAL_appendvars(t, 2); PRIMAL_appendcons(t, 2);
    PRIMAL_putcj(t, 0, 1.0); PRIMAL_putcj(t, 1, 0.0);
    PRIMAL_putconbound(t, 0, PRIMAL_BK_FX, 5, 5);
    PRIMAL_putconbound(t, 1, PRIMAL_BK_FX, 1, 1);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_FR, 0, 0);
    PRIMAL_putvarbound(t, 1, PRIMAL_BK_FR, 0, 0);
    int s0[] = {0,1}; double v0[] = {1,1};
    int s1[] = {0,1}; double v1[] = {1,-1};
    PRIMAL_putacol(t, 0, 2, s0, v0);
    PRIMAL_putacol(t, 1, 2, s1, v1);
    PRIMALrescodee rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_OK, "optimize ok");
    double x[2], po, y[2];
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x);
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &po);
    close_enough(po, 3, "pobj=3");
    close_enough(x[0], 3, "x1=3");
    close_enough(x[1], 2, "x2=2");
    PRIMAL_gety(t, PRIMAL_SOL_ITR, y);
    close_enough(y[0], -0.5, "y1=-0.5");
    close_enough(y[1], -0.5, "y2=-0.5");
    expect_kkt(t, 1.0);
    pend(&p);
}

/* T4: min -x, x <= 5 (BK_UP), row x+y = 10, y >= 0 */
static void test_t4(void) {
    cur_name = "T4 BK_UP variable, min -x";
    P p; pbegin(&p);
    PRIMALtask_t t = p.task;
    PRIMAL_appendvars(t, 2); PRIMAL_appendcons(t, 1);
    PRIMAL_putcj(t, 0, -1.0); PRIMAL_putcj(t, 1, 0.0);
    PRIMAL_putconbound(t, 0, PRIMAL_BK_FX, 10, 10);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_UP, 0, 5);
    PRIMAL_putvarbound(t, 1, PRIMAL_BK_LO, 0, 0);
    int s0[] = {0}; double v0[] = {1};
    int s1[] = {0}; double v1[] = {1};
    PRIMAL_putacol(t, 0, 1, s0, v0);
    PRIMAL_putacol(t, 1, 1, s1, v1);
    PRIMALrescodee rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_OK, "optimize ok");
    double x[2], po, y[1], sux[2];
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x);
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &po);
    close_enough(po, -5, "pobj=-5");
    close_enough(x[0], 5, "x=5");
    close_enough(x[1], 5, "y=5");
    PRIMAL_gety(t, PRIMAL_SOL_ITR, y);
    close_enough(y[0], 0, "y_rep=0");
    PRIMAL_getsux(t, PRIMAL_SOL_ITR, sux);
    close_enough(sux[0], 1, "sux_x=1");
    expect_kkt(t, 1.0);
    pend(&p);
}

/* T5: infeasible: x >= 5 and x <= 3 */
static void test_t5(void) {
    cur_name = "T5 infeasible (x>=5, x<=3)";
    P p; pbegin(&p);
    PRIMALtask_t t = p.task;
    PRIMAL_appendvars(t, 1); PRIMAL_appendcons(t, 2);
    PRIMAL_putcj(t, 0, 1.0);
    PRIMAL_putconbound(t, 0, PRIMAL_BK_LO, 5, 0);
    PRIMAL_putconbound(t, 1, PRIMAL_BK_UP, 0, 3);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_FR, 0, 0);
    int s0[] = {0,1}; double v0[] = {1,1};
    PRIMAL_putacol(t, 0, 2, s0, v0);
    PRIMALrescodee rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_ERR_INFEASIBLE, "rc=ERR_INFEASIBLE");
    PRIMALsolstae sta; PRIMAL_getsolsta(t, PRIMAL_SOL_ITR, &sta);
    check(sta == PRIMAL_SOL_STA_PRIM_INFEAS_CER, "PRIM_INFEAS_CER");
    pend(&p);
}

/* T5b: same infeasible via interior point */
static void test_t5b(void) {
    cur_name = "T5b infeasible via INTPNT (must not claim optimal)";
    P p; pbegin(&p);
    PRIMALtask_t t = p.task;
    PRIMAL_appendvars(t, 1); PRIMAL_appendcons(t, 2);
    PRIMAL_putintparam(t, PRIMAL_IPAR_OPTIMIZER, PRIMAL_OPTIMIZER_INTPNT);
    PRIMAL_putcj(t, 0, 1.0);
    PRIMAL_putconbound(t, 0, PRIMAL_BK_LO, 5, 0);
    PRIMAL_putconbound(t, 1, PRIMAL_BK_UP, 0, 3);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_FR, 0, 0);
    int s0[] = {0,1}; double v0[] = {1,1};
    PRIMAL_putacol(t, 0, 2, s0, v0);
    PRIMALrescodee rc = PRIMAL_optimize(t);
    check(rc != PRIMAL_RES_OK, "rc != OK");
    PRIMALsolstae sta; PRIMAL_getsolsta(t, PRIMAL_SOL_ITR, &sta);
    check(sta != PRIMAL_SOL_STA_OPTIMAL, "not OPTIMAL");
    pend(&p);
}

/* T6: unbounded: min -x, x FR */
static void test_t6(void) {
    cur_name = "T6 unbounded (min -x, x free)";
    P p; pbegin(&p);
    PRIMALtask_t t = p.task;
    PRIMAL_appendvars(t, 1);
    PRIMAL_putcj(t, 0, -1.0);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_FR, 0, 0);
    PRIMALrescodee rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_ERR_UNBOUNDED, "rc=ERR_UNBOUNDED");
    PRIMALsolstae sta; PRIMAL_getsolsta(t, PRIMAL_SOL_ITR, &sta);
    check(sta == PRIMAL_SOL_STA_DUAL_INFEAS_CER, "DUAL_INFEAS_CER");
    pend(&p);
}

/* T7: ranged row 1 <= x1+x2 <= 3, min -2x1-x2 */
static void test_t7(void) {
    cur_name = "T7 ranged constraint 1<=x+y<=3";
    P p; pbegin(&p);
    PRIMALtask_t t = p.task;
    PRIMAL_appendvars(t, 2); PRIMAL_appendcons(t, 1);
    PRIMAL_putcj(t, 0, -2.0); PRIMAL_putcj(t, 1, -1.0);
    PRIMAL_putconbound(t, 0, PRIMAL_BK_RA, 1, 3);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_LO, 0, 0);
    PRIMAL_putvarbound(t, 1, PRIMAL_BK_LO, 0, 0);
    int s0[] = {0}; double v0[] = {1};
    int s1[] = {0}; double v1[] = {1};
    PRIMAL_putacol(t, 0, 1, s0, v0);
    PRIMAL_putacol(t, 1, 1, s1, v1);
    PRIMALrescodee rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_OK, "optimize ok");
    double x[2], po, y[1];
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x);
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &po);
    close_enough(po, -6, "pobj=-6");
    close_enough(x[0], 3, "x1=3");
    close_enough(x[1], 0, "x2=0");
    PRIMAL_gety(t, PRIMAL_SOL_ITR, y);
    close_enough(y[0], 2, "y=2 (upper side)");
    expect_kkt(t, 1.0);
    pend(&p);
}

/* T8: Beale's cycling example (anti-cycling regression) */
static void test_t8(void) {
    cur_name = "T8 Beale cycling example";
    P p; pbegin(&p);
    PRIMALtask_t t = p.task;
    /* min -0.75x4 + 150x5 - 0.02x6 + 6x7
       s.t. 0.25x4 - 60x5 - 0.04x6 + 9x7  <= 0
            0.50x4 - 90x5 - 0.02x6 + 3x7  <= 0
            x6 <= 1
       x >= 0  (x4..x7 here are the 4 vars, indices 0..3) */
    PRIMAL_appendvars(t, 4); PRIMAL_appendcons(t, 3);
    double c[] = {-0.75, 150, -0.02, 6};
    for (int j = 0; j < 4; j++) PRIMAL_putcj(t, j, c[j]);
    PRIMAL_putconbound(t, 0, PRIMAL_BK_UP, 0, 0);
    PRIMAL_putconbound(t, 1, PRIMAL_BK_UP, 0, 0);
    PRIMAL_putconbound(t, 2, PRIMAL_BK_UP, 0, 1);
    for (int j = 0; j < 4; j++) PRIMAL_putvarbound(t, j, PRIMAL_BK_LO, 0, 0);
    int sa[] = {0,1};   double va[] = {0.25,0.5};
    int sb[] = {0,1};   double vb[] = {-60,-90};
    int sc[] = {0,1,2}; double vc[] = {-0.04,-0.02,1};
    int sd[] = {0,1};   double vd[] = {9,3};
    PRIMAL_putacol(t, 0, 2, sa, va);
    PRIMAL_putacol(t, 1, 2, sb, vb);
    PRIMAL_putacol(t, 2, 3, sc, vc);
    PRIMAL_putacol(t, 3, 2, sd, vd);
    PRIMALrescodee rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_OK, "optimize ok");
    double x[4], po;
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x);
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &po);
    close_enough(po, -0.05, "pobj=-0.05");
    close_enough(x[0], 0.04, "x4=0.04");
    close_enough(x[1], 0, "x5=0");
    close_enough(x[2], 1, "x6=1");
    close_enough(x[3], 0, "x7=0");
    expect_kkt(t, 1.0);
    pend(&p);
}

