/* T13: mid-size LP/QP cross-validation simplex vs INTPNT
 * min 1/2|x|^2 - x*'x  s.t. Ax = b  (x* > 0 known) */
static void test_t13(void) {
    cur_name = "T13 QP cross-validation (x*=known, obj=-1/2|x*|^2)";
    int n = 6;
    double xs[] = {0.5, 1.0, 1.5, 2.0, 2.5, 3.0};
    P p; pbegin(&p);
    PRIMALtask_t t = p.task;
    PRIMAL_appendvars(t, n); PRIMAL_appendcons(t, n);
    for (int j = 0; j < n; j++) {
        PRIMAL_putcj(t, j, -xs[j]);
        PRIMAL_putvarbound(t, j, PRIMAL_BK_LO, 0, 0);
        int s[1] = {j}; double v[1] = {2.0 + 0.5 * j};
        PRIMAL_putacol(t, j, 1, s, v);
        double b = (2.0 + 0.5 * j) * xs[j];
        PRIMAL_putconbound(t, j, PRIMAL_BK_FX, b, b);
    }
    { int qi[6], qj[6]; double qv[6];
      for (int j = 0; j < 6; j++) { qi[j] = j; qj[j] = j; qv[j] = 1; }
      PRIMAL_putqobj(t, 6, qi, qj, qv); }
    PRIMALrescodee rc = PRIMAL_optimize(t);
    check(rc == PRIMAL_RES_OK, "optimize ok (IPM)");
    double x[6], po;
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x);
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &po);
    double target = 0.0;
    for (int j = 0; j < n; j++) target += 0.5 * xs[j] * xs[j];
    close_enough(po, -target, "pobj=-1/2|x*|^2");
    for (int j = 0; j < n; j++) close_enough(x[j], xs[j], "x=x*");
    expect_kkt(t, 1.0);
    pend(&p);
}

/* T13b: LP cross-validation: same problem without Q, objective -x*'x,
 * optimum at a vertex; simplex and IPM must agree on pobj */
static void test_t13b(void) {
    cur_name = "T13b LP simplex vs INTPNT cross-validation";
    /* min -x1-x2 s.t. x1+x2<=4, x1+3x2<=6, x>=0 -> opt (4,0) obj -4 */
    P p; pbegin(&p);
    PRIMALtask_t t = p.task;
    PRIMAL_appendvars(t, 2); PRIMAL_appendcons(t, 2);
    PRIMAL_putcj(t, 0, -1.0); PRIMAL_putcj(t, 1, -1.0);
    PRIMAL_putconbound(t, 0, PRIMAL_BK_UP, 0, 4);
    PRIMAL_putconbound(t, 1, PRIMAL_BK_UP, 0, 6);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_LO, 0, 0);
    PRIMAL_putvarbound(t, 1, PRIMAL_BK_LO, 0, 0);
    int s0[] = {0}; double v0[] = {1};
    int s1[] = {0,1}; double v1[] = {1,3};
    PRIMAL_putacol(t, 0, 1, s0, v0);
    PRIMAL_putacol(t, 1, 2, s1, v1);

    PRIMAL_putintparam(t, PRIMAL_IPAR_OPTIMIZER, PRIMAL_OPTIMIZER_PRIMAL_SIMPLEX);
    PRIMALrescodee rc = PRIMAL_optimize(t);
    check(rc == PRIMAL_RES_OK, "simplex ok");
    double po_s, po_i, x_s[2];
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &po_s);
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x_s);
    close_enough(po_s, -4, "simplex pobj=-4");

    PRIMAL_putintparam(t, PRIMAL_IPAR_OPTIMIZER, PRIMAL_OPTIMIZER_INTPNT);
    rc = PRIMAL_optimize(t);
    check(rc == PRIMAL_RES_OK, "ipm ok");
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &po_i);
    close_enough(po_i, po_s, "IPM obj == simplex obj");
    expect_kkt(t, 1.0);
    pend(&p);
}

/* T17: cfix and writedata/getters round-trip */
static void test_t17(void) {
    cur_name = "T17 cfix, getters, writedata";
    P p; pbegin(&p);
    PRIMALtask_t t = p.task;
    PRIMAL_appendvars(t, 2); PRIMAL_appendcons(t, 1);
    PRIMAL_putcj(t, 0, 1.0); PRIMAL_putcj(t, 1, 1.0);
    PRIMAL_putcfix(t, 7.5);
    PRIMAL_putconbound(t, 0, PRIMAL_BK_FX, 2, 2);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_LO, 0, 0);
    PRIMAL_putvarbound(t, 1, PRIMAL_BK_LO, 0, 0);
    int s0[] = {0}; double v0[] = {1};
    PRIMAL_putacol(t, 0, 1, s0, v0);
    PRIMAL_putacol(t, 1, 1, s0, v0);
    PRIMALrescodee rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_OK, "optimize ok");
    double po, cf;
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &po);
    PRIMAL_getcfix(t, &cf);
    close_enough(cf, 7.5, "getcfix");
    close_enough(po, 9.5, "pobj includes cfix");
    /* The dual must carry the same constant: the LP part alone is worth 2.0,
     * pobj is 9.5, so a dobj that drops cfix misses by exactly 7.5. */
    double dobj;
    check_rc(PRIMAL_getdualobj(t, PRIMAL_SOL_ITR, &dobj), PRIMAL_RES_OK, "getdualobj");
    close_enough(dobj, po, "dobj carries cfix (strong duality)");
    /* getters round-trip */
    double cj; PRIMAL_getcj(t, 1, &cj);
    close_enough(cj, 1.0, "getcj");
    double aij; PRIMAL_getaij(t, 0, 1, &aij);
    close_enough(aij, 1.0, "getaij");
    PRIMALboundkeye bk; double bl, bu;
    PRIMAL_getvarbound(t, 0, &bk, &bl, &bu);
    check(bk == PRIMAL_BK_LO && bl == 0.0, "getvarbound");
    PRIMALobjsensee se; PRIMAL_getobjsense(t, &se);
    check(se == PRIMAL_OPTIMIZE_MINIMIZE, "getobjsense");
    rc = PRIMAL_writedata(t, "work_dump.txt");
    check(rc == PRIMAL_RES_OK, "writedata ok");
    remove("work_dump.txt");
    pend(&p);
}

