/* T20: degenerate LP - multiple optima, duals must still be KKT-valid */
static void test_t20(void) {
    cur_name = "T20 degenerate LP (dual non-uniqueness)";
    /* min x1+x2 s.t. x1+x2>=2, x1<=1, x2<=1 -> any (1,1); duals non-unique */
    P p; pbegin(&p);
    PRIMALtask_t t = p.task;
    PRIMAL_appendvars(t, 2); PRIMAL_appendcons(t, 3);
    PRIMAL_putcj(t, 0, 1.0); PRIMAL_putcj(t, 1, 1.0);
    PRIMAL_putconbound(t, 0, PRIMAL_BK_LO, 2, 0);
    PRIMAL_putconbound(t, 1, PRIMAL_BK_UP, 0, 1);
    PRIMAL_putconbound(t, 2, PRIMAL_BK_UP, 0, 1);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_LO, 0, 0);
    PRIMAL_putvarbound(t, 1, PRIMAL_BK_LO, 0, 0);
    int s0[] = {0,1,2}; double v0[] = {1,1,0};
    int s1[] = {0,1,2}; double v1[] = {1,0,1};
    PRIMAL_putacol(t, 0, 3, s0, v0);
    PRIMAL_putacol(t, 1, 3, s1, v1);
    PRIMALrescodee rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_OK, "optimize ok");
    double x[2], po;
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x);
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &po);
    close_enough(po, 2, "pobj=2");
    close_enough(x[0], 1, "x1=1");
    close_enough(x[1], 1, "x2=1");
    expect_kkt(t, 1.0);
    pend(&p);
}


/* T21: conic QUAD cone + FX row: min -x1 s.t. x1=1, (t,x1,x2) in Q^3 */
static void test_t21(void) {
    cur_name = "T21 conic: SOC cone, FX row";
    PRIMALenv_t env; PRIMALtask_t t;
    PRIMAL_makeenv(&env, NULL);
    PRIMAL_maketask(env, 1, 3, &t);
    int j0 = 0;
    PRIMAL_putacol(t, 1, 1, &j0, (double[]){1.0});
    PRIMAL_putconbound(t, 0, PRIMAL_BK_FX, 1.0, 1.0);
    PRIMAL_putcj(t, 1, -1.0);
    for (int j = 0; j < 3; j++) PRIMAL_putvarbound(t, j, PRIMAL_BK_FR, 0.0, 0.0);
    PRIMALrescodee rc = PRIMAL_appendcone(t, PRIMAL_CT_QUAD, 0.0, 3, (int[]){0, 1, 2});
    check_rc(rc, PRIMAL_RES_OK, "appendcone");
    rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_OK, "optimize");
    PRIMALsolstae ss; PRIMAL_getsolsta(t, PRIMAL_SOL_ITR, &ss);
    check(ss == PRIMAL_SOL_STA_OPTIMAL, "solsta OPTIMAL");
    double x[3], dobj, pobj;
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x);
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &pobj);
    PRIMAL_getdualobj(t, PRIMAL_SOL_ITR, &dobj);
    close_enough(pobj, -1.0, "pobj");
    close_enough(dobj, -1.0, "dobj");
    close_enough(x[1], 1.0, "x1");
    /* t has zero objective cost: IPM leaves it slightly suboptimal */
    check(fabs(x[0] - 1.0) <= 1e-2, "t near-optimal");
    PRIMAL_deletetask(&t); PRIMAL_deleteenv(&env);
}

/* T22: conic distance: min t s.t. x1+x2=10, (t,x1,x2) in Q^3 -> t=10/sqrt2 */
