/* T23: conic RQUAD via aux vars: min -x1 s.t. (u,x2,x1) in RQUAD, u=1,
 * x2<=2 -> 2*u*x2 >= x1^2 -> x1=2, x2=2, obj=-2 */
static void test_t23(void) {
    cur_name = "T23 conic: rotated quadratic cone";
    PRIMALenv_t env; PRIMALtask_t t;
    PRIMAL_makeenv(&env, NULL);
    PRIMAL_maketask(env, 0, 3, &t);
    PRIMAL_putcj(t, 2, -1.0);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_FX, 1.0, 1.0);
    PRIMAL_putvarbound(t, 1, PRIMAL_BK_UP, 0.0, 2.0);
    PRIMAL_putvarbound(t, 2, PRIMAL_BK_FR, 0.0, 0.0);
    PRIMALrescodee rc = PRIMAL_appendcone(t, PRIMAL_CT_RQUAD, 0.0, 3, (int[]){0, 1, 2});
    check_rc(rc, PRIMAL_RES_OK, "appendcone");
    rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_OK, "optimize");
    double x[3], dobj;
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x);
    PRIMAL_getdualobj(t, PRIMAL_SOL_ITR, &dobj);
    close_enough(x[2], 2.0, "x1");
    close_enough(x[1], 2.0, "x2");
    close_enough(dobj, -2.0, "dobj");
    /* cone membership: 2*u*x2 >= x1^2 */
    check(2.0 * x[0] * x[1] >= x[2] * x[2] - 1e-6, "rotated cone satisfied");
    PRIMAL_deletetask(&t); PRIMAL_deleteenv(&env);
}

/* T24: MIP: min -7x1-2x2 s.t. -x1+2x2<=4, 5x1+x2<=20, -2x1-2x2<=-7,
 * x1,x2 int >=0 -> integer optimum x=(4,0), obj=-28 */
static void test_t24(void) {
    cur_name = "T24 MIP: integer LP";
    PRIMALenv_t env; PRIMALtask_t t;
    PRIMAL_makeenv(&env, NULL);
    PRIMAL_maketask(env, 3, 2, &t);
    PRIMAL_putacol(t, 0, 3, (int[]){0, 1, 2}, (double[]){-1.0, 5.0, -2.0});
    PRIMAL_putacol(t, 1, 3, (int[]){0, 1, 2}, (double[]){2.0, 1.0, -2.0});
    PRIMAL_putconbound(t, 0, PRIMAL_BK_UP, 0.0, 4.0);
    PRIMAL_putconbound(t, 1, PRIMAL_BK_UP, 0.0, 20.0);
    PRIMAL_putconbound(t, 2, PRIMAL_BK_UP, 0.0, -7.0);
    PRIMAL_putcj(t, 0, -7.0);
    PRIMAL_putcj(t, 1, -2.0);
    for (int j = 0; j < 2; j++) {
        PRIMAL_putvarbound(t, j, PRIMAL_BK_LO, 0.0, 0.0);
        PRIMAL_putvartype(t, j, PRIMAL_VAR_TYPE_INT);
    }
    int nint;
    PRIMAL_getnumintvar(t, &nint);
    check(nint == 2, "numintvar");
    PRIMALvariabletypee vt;
    PRIMAL_getvartype(t, 1, &vt);
    check(vt == PRIMAL_VAR_TYPE_INT, "getvartype");
    PRIMALrescodee rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_OK, "optimize");
    PRIMALsolstae ss;
    PRIMAL_getsolsta(t, PRIMAL_SOL_ITR, &ss);
    check(ss == PRIMAL_SOL_STA_INTEGER_OPTIMAL, "solsta integer optimal");
    double x[2], pobj;
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x);
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &pobj);
    close_enough(x[0], 4.0, "x1");
    close_enough(x[1], 0.0, "x2");
    close_enough(pobj, -28.0, "pobj");
    close_enough(x[0], floor(x[0] + 1e-9), "x1 integral");
    close_enough(x[1], floor(x[1] + 1e-9), "x2 integral");
    PRIMAL_deletetask(&t); PRIMAL_deleteenv(&env);
}

