/* T26: MIP infeasible: x int, x<=0.5 and x>=1 -> ERR_INFEASIBLE +
 * prosta PRIM_INFEAS + solsta UNKNOWN.
 *
 * The solution status used to be PRIM_INFEAS_CER. The reference's table for
 * integer problems (accessing the solution, Table 7.3) pairs an infeasible
 * mixed-integer model with PRIM_INFEAS and UNKNOWN, and this solver's own rule
 * is that a certificate status does not go out without the vector that measures
 * it: branch-and-bound has no Farkas ray to publish, so the verdict is the
 * problem status alone. The return code still says infeasible (our rc numbering
 * is our own, declared in README). */
static void test_t26(void) {
    cur_name = "T26 MIP: infeasible";
    PRIMALenv_t env; PRIMALtask_t t;
    PRIMAL_makeenv(&env, NULL);
    PRIMAL_maketask(env, 2, 1, &t);
    PRIMAL_putacol(t, 0, 2, (int[]){0, 1}, (double[]){1.0, 1.0});
    PRIMAL_putconbound(t, 0, PRIMAL_BK_UP, 0.0, 0.5);
    PRIMAL_putconbound(t, 1, PRIMAL_BK_LO, 1.0, 0.0);
    PRIMAL_putcj(t, 0, 1.0);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_LO, 0.0, 0.0);
    PRIMAL_putvartype(t, 0, PRIMAL_VAR_TYPE_INT);
    PRIMALrescodee rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_ERR_INFEASIBLE, "infeasible rc");
    PRIMALsolstae ss; PRIMALprostae ps;
    PRIMAL_getsolsta(t, PRIMAL_SOL_ITR, &ss);
    PRIMAL_getprosta(t, PRIMAL_SOL_ITR, &ps);
    check(ss == PRIMAL_SOL_STA_UNKNOWN, "solsta unknown su MIP infeasibile");
    check(ps == PRIMAL_PRO_STA_PRIM_INFEAS && (int)ps == 4,
          "prosta prim infeas = 4 (tabella 7.3)");
    {   double yy[4];
        check_rc(PRIMAL_getdualray(t, yy), PRIMAL_RES_ERR_ARG,
                 "T26 nessun raggio senza certificato"); }
    PRIMAL_deletetask(&t); PRIMAL_deleteenv(&env);
}

/* T27: MIP with equality row and mixed bounds: min x1+x2+2x3,
 * x1+x2+x3=10, x1<=5, x2<=3, x3<=6, all int >=0 -> 5*1+3*1+2*2=12 */
static void test_t27(void) {
    cur_name = "T27 MIP: equality + branching";
    PRIMALenv_t env; PRIMALtask_t t;
    PRIMAL_makeenv(&env, NULL);
    PRIMAL_maketask(env, 1, 3, &t);
    PRIMAL_putacol(t, 0, 1, (int[]){0}, (double[]){1.0});
    PRIMAL_putacol(t, 1, 1, (int[]){0}, (double[]){1.0});
    PRIMAL_putacol(t, 2, 1, (int[]){0}, (double[]){1.0});
    PRIMAL_putconbound(t, 0, PRIMAL_BK_FX, 10.0, 10.0);
    PRIMAL_putcj(t, 0, 1.0);
    PRIMAL_putcj(t, 1, 1.0);
    PRIMAL_putcj(t, 2, 2.0);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_UP, 0.0, 5.0);
    PRIMAL_putvarbound(t, 1, PRIMAL_BK_UP, 0.0, 3.0);
    PRIMAL_putvarbound(t, 2, PRIMAL_BK_UP, 0.0, 6.0);
    for (int j = 0; j < 3; j++)
        PRIMAL_putvartype(t, j, PRIMAL_VAR_TYPE_INT);
    PRIMALrescodee rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_OK, "optimize");
    double x[3], pobj;
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x);
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &pobj);
    close_enough(x[0], 5.0, "x1");
    close_enough(x[1], 3.0, "x2");
    close_enough(x[2], 2.0, "x3");
    close_enough(pobj, 12.0, "pobj");
    PRIMAL_deletetask(&t); PRIMAL_deleteenv(&env);
}

/* ---- I/O roundtrip helpers (T28-T32) ---- */
static void solve_and_check(const char *file, double ex0, double ex1,
                            double pexp, const char *what) {
    PRIMALenv_t env; PRIMALtask_t t;
    PRIMAL_makeenv(&env, NULL);
    PRIMAL_maketask(env, 0, 0, &t);
    PRIMALrescodee rc = PRIMAL_readdata(t, file);
    check_rc(rc, PRIMAL_RES_OK, "readdata");
    if (rc != PRIMAL_RES_OK) { PRIMAL_deletetask(&t); PRIMAL_deleteenv(&env); return; }
    rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_OK, "optimize");
    double x[8], pobj;
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x);
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &pobj);
    close_enough(x[0], ex0, what);
    close_enough(x[1], ex1, what);
    close_enough(pobj, pexp, what);
    PRIMAL_deletetask(&t); PRIMAL_deleteenv(&env);
}

/* T28: LP MPS roundtrip: min -x1-2x2 s.t. x1+x2<=4, x1+3x2<=6, 0<=x<=3 */
