    PRIMAL_putacol(t, 1, 2, (int[]){0,1}, (double[]){1.0,3.0});
    PRIMAL_putconbound(t, 0, PRIMAL_BK_UP, -INFINITY, 4.0);
    PRIMAL_putconbound(t, 1, PRIMAL_BK_UP, -INFINITY, 6.0);
    PRIMAL_putcj(t, 0, -1.0); PRIMAL_putcj(t, 1, -2.0);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_RA, 0.0, 3.0);
    PRIMAL_putvarbound(t, 1, PRIMAL_BK_RA, 0.0, 3.0);
